@Component
struct WarehouseAccumulator {
  @State total: number = 0
  private rows: StockRow[] = []
  refresh() {
    this.total = 0
    this.rows.forEach((row: StockRow) => {
      this.total += row.quantity
    })
  }

@Component
struct WarehouseList {
  @State rows: StockRow[] = []
  build() {
    Column() {
      ForEach(this.rows, (row: StockRow) => {
        Text(`${row.quantity}`)
      })
    }
  }
}

@Component
struct WarehouseDeferred {
  @State total: number = 0
  private rows: StockRow[] = []
  refresh() {
    this.rows.forEach((row: StockRow) => {
      queueMicrotask(() => { this.total += row.quantity })
    })
  }
}
